namespace ghidra.app.plugin.core.bookmark;

using ghidra.framework.cmd;
using ghidra.program.model.listing;
using ghidra.util.task;

/**
 * Command to delete a number of bookmarks.
 */
public class BookmarkDeleteBackgroundCmd : BackgroundCommand<Program> {

	private Bookmark[] bookmarks;

	/**
	 * Delete an array of Bookmarks.
	 * @param bookmarks the array of bookmarks to be deleted.
	 */
	public BookmarkDeleteBackgroundCmd(Bookmark[] bookmarks) : base("Delete Bookmarks", true, true, false)
    {
		this.bookmarks = bookmarks;
	}

	/**
	 * @see ghidra.framework.cmd.BackgroundCommand#applyTo(ghidra.framework.model.DomainObject, ghidra.util.task.TaskMonitor)
	 */
	/* @Override */
	public bool applyTo(Program program, TaskMonitor monitor) {
		BookmarkManager mgr = program.getBookmarkManager();
		monitor.initialize(bookmarks.length);
		for (int i = 0; i < bookmarks.length; i++) {
			if (monitor.isCancelled()) {
				return true;
			}
			Bookmark bm = bookmarks[i];
			mgr.removeBookmark(bm);
			monitor.setProgress(i);
		}
		return true;
	}
}
